请对以下 case 进行三维加权评分。

=== case_id ===
Case-21-stocks-004

=== 用户原始指令 (query.txt) ===
帮我弄个基金涨跌图,上面写今日盈亏,点了进app,跌太多红字提醒

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄个基金涨跌图,上面写今日盈亏,点了进app,跌太多红字提醒",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "fund": {
      "title": {
        "type": "string",
        "description": "基金卡片标题，标识当前展示的是基金收益概览。",
        "sampleValue": "基金涨跌"
      },
      "changePercent": {
        "type": "string",
        "description": "当前基金日内涨跌幅展示文本。",
        "sampleValue": "-3.28%"
      },
      "profitText": {
        "type": "string",
        "description": "今日盈亏金额展示文本。",
        "sampleValue": "-128.60"
      },
      "statusColor": {
        "type": "string",
        "description": "跌幅过大时用于主盈亏和提醒文字的红色状态色。",
        "sampleValue": "#ffed6f21"
      },
      "dropScore": {
        "type": "number",
        "description": "跌幅风险进度值，用于展示下跌程度的简化涨跌图。",
        "sampleValue": 78
      },
      "dropTotal": {
        "type": "number",
        "description": "跌幅风险进度总量，用于计算涨跌图比例。",
        "sampleValue": 100
      },
      "alertText": {
        "type": "string",
        "description": "跌幅过大时展示的红字提醒。",
        "sampleValue": "跌幅偏大"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/bell_fill.svg",
      "description": "铃铛实心提醒图标，黑色，适合用于通知提醒、风险提醒或需要用户关注的状态提示。"
    }
  ]
}

